INSERT INTO `companies` (`id`, `visi`, `misi`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'Berani mewujudkan Sulawesi Tengah sebagai Wilayah Pertanian dan Industri yang Maju dan Berkelanjutan 2025-2029', '<p style=\"text-align: justify;\">&ldquo;Berani mewujudkan Sulawesi Tengah sebagai Wilayah Pertanian dan Industri yang Maju dan Berkelanjutan Tahun 2025 &ndash; 2029 dengan Misi sebagai berikut:</p>\r\n<ol>\r\n<li style=\"text-align: justify;\">Mewujudkan Masyarakat Sehat, Cerdas dan Sejahtera melalui Pemenuhan kebutuhan dasar dan penyediaan lapangan kerja.</li>\r\n<li style=\"text-align: justify;\">Mewujudkan Masyarakat Bahagia dan Produktif melalui peningkatan ekonomi berbasis potensi unggulan daerah dan pemberdayaan ekonomi kerakyatan yang berkeadilan.</li>\r\n<li style=\"text-align: justify;\">Mewujudkan Pembangunan berbasis Lingkungan dan Tata Ruang yang Berkelanjutan berorientasi pada konektivitas antar wilayah dan antar sektor.</li>\r\n<li style=\"text-align: justify;\">Meningkatkan Tata Kelola Pemerintahan bersih, inovatif, kaloboratif serta keamanan daerah yang Tangguh berlandaskan nilai religious dan kearifan lokal.</li>\r\n</ol>\r\n<p style=\"text-align: justify;\">Dalam pencapaian <strong>Visi dan Misi Gubernur Sulawesi Tengah, Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah </strong>sesuai dengan tugas dan fungsinya dalam mendukung :</p>\r\n<p style=\"text-align: justify;\"><strong>Misi 1 :</strong></p>\r\n<p style=\"text-align: justify;\">Mewujudkan Masyarakat sehat, cerdas dan Sejahtera melalui pemenuhan kebutuhan dasar dan penyediaan lapangan kerja.</p>\r\n<p style=\"text-align: justify;\"><strong>Misi 4 :</strong></p>\r\n<p style=\"text-align: justify;\">Memperkuat birokrasi yang akuntabel, membangun budaya kerja yang bersih, mencegah terjadinya tindak korupsi dan menjamin seluruh kegiatan pemerintahan berjalan tepat sasaran.</p>\r\n<p style=\"text-align: justify;\">Berdasarkan hasil telaah Visi, dan Misi Gubernur Sulawesi Tengah maka Tujuan pelaksanaan pembangunan yang akan dicapai Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah Tahun 2025 &ndash; 2029 mendatang adalah &ldquo;Meningkatnya literasi masyarakat, tata kelola Kearsipan dan tingkat digitalisasi Arsip&rdquo;. Penetapan tujuan dari misi ini berdasarkan hasil telaah kesesuaian RPJMD Tahun 2025-2029 Provinsi Sulawesi Tengah dengan tugas dan fungsi Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah.</p>\r\n<p style=\"text-align: justify;\">Untuk mencapai tujuan tersebut Maka Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah menetapkan sasaran strategis jangka menengah yang merupakan indikator pencapaian hasil yang diharapkan dari suatu tujuan yang diformulasikan secara terukur, spesifik, mudah dicapai, rasional, untuk dapat dilaksanakan dalam jangka waktu 5 (lima) tahun ke depan.</p>', 'Admin Website', 'Admin Website', '2026-08-28 13:31:56', '2026-09-03 17:55:32');
INSERT INTO `faqlayanans` (`id`, `judul`, `isi`, `status_id`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'Bagaimana cara menjadi anggota perpustakaan?', '<p><span class=\"iNqyIf\" data-sfc-cp=\"\" data-sfc-root=\"ep\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 400; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\"><strong class=\"rQesXe MPyX\" data-sfc-cp=\"\" data-sfc-root=\"ep\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 700; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\">Isi Formulir:<!--TgQPHd|||[]--></strong> Buka gawai atau komputer Anda, lalu isi data diri secara lengkap melalui tautan resmi <span class=\"iNqyIf\" data-sfc-cp=\"\" data-sfc-root=\"ep\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 400; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\">Keanggotaan Perpustakaan Sulteng<!--TgQPHd|||[]--></span>.</span></p>\r\n<p><span class=\"iNqyIf\" data-sfc-cp=\"\" data-sfc-root=\"ep\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 400; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\"><strong class=\"rQesXe MPyX\" data-sfc-cp=\"\" data-sfc-root=\"ep\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 700; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\">Gunakan Identitas Asli:<!--TgQPHd|||[]--></strong> Pastikan data yang dimasukkan (nama, nomor identitas, alamat) sesuai dengan KTP, KIA, atau Kartu Pelajar yang sah agar proses verifikasi berjalan lancar.</span></p>\r\n<p><span class=\"iNqyIf\" data-sfc-cp=\"\" data-sfc-root=\"ep\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 400; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\"><strong class=\"rQesXe MPyX\" data-sfc-cp=\"\" data-sfc-root=\"ep\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 700; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\">Konfirmasi &amp; Cetak Kartu:<!--TgQPHd|||[]--></strong> Setelah data diverifikasi oleh sistem, Anda bisa datang langsung ke gedung layanan untuk melakukan pengambilan foto profil dan pencetakan fisik kartu anggota perpustakaan.<!--TgQPHd|||[]--></span><!--TgQPHd|||[]--></p>', '1', 'Admin Website', 'Admin Website', '2026-08-25 23:55:10', '2026-08-28 00:16:30');
INSERT INTO `histories` (`id`, `sejarah_instansi`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, '<p style=\"text-align: justify;\">Cikal bakal perpustakaan di Sulawesi Tengah dimulai dengan terbentuknya Perpustakaan Wilayah Departemen Pendidikan dan Kebudayaan (Depdikbud) dengan SK Menteri Pendidikan dan Kebudayaan (Mendikud) No. 09199/1978 tanggal 23 Juli 1978; sedangkan susunan organisasi, tata kerja, serta penggolongan tipenya ditetapkan dengan SK Mendikbud No. 095/0/1979. Dalam rangka pembentukan Perpustakaan Nasional yang didirikan berdasarkan SK Mendikbud No. 0164/0/1980, maka secara resmi berdiri Perpustakaan Wilayah Provinsi Sulawesi Tengah yang merupakan Unit Pelaksana Teknis (UPT) di lingkungan Dirjen Depdikbud Provinsi Sulawesi Tengah dan secara vertikal bertanggung jawab langsung pada Pusat Pembinaan Perpustakaan, Depdikbud di Jakarta.</p>\r\n<p style=\"text-align: justify;\">Sejak diterbitkannya SK Presiden No. 11/1989 tentang Perpustakaan Nasional, maka Pusat&nbsp;Pembinaan Perpustakaan diintegrasikan ke dalam Perpustakaan Nasional RI, sedangkan&nbsp;di Daerah Tingkat I semua perpustakaan wilayah dialihfungsikan menjadi perpustakaan daerah&nbsp;provinsi yang merupakan satuan organisasi di lingkungan Perpustakaan Nasional RI.&nbsp;Pembentukan perpustakaan daerah dilakukan dan ditetapkan dengan Keputusan Kepala&nbsp;Perpustakan Nasional RI No. 001/Org/9/1990 tentang organisasi dan tata kerja Perpustakaan Nasional&nbsp;dan secara penuh peralihan tersebut baru terealisasi sejak tanggal 1 April 1991.&nbsp;Setelah diberlakukan UU No. 22 tahun 1999 tentang Otonomi Daerah dan UU No. 33 tahun 1999&nbsp;tentang Perimbangan Keuangan Pusat dan Daerah, maka Perpustakaan Daerah Provinsi Sulawesi Tengah&nbsp;mengalami perubahan status organisasi dari instansi vertikal menjadi Satuan Kerja Perangkat Daerah&nbsp;(SKPD) Provinsi dengan nama Badan Perpustakaan Daerah Provinsi Sulawesi Tengah berdasarkan&nbsp;Peraturan Daerah No. 15 tahun 2001 tentang Organisasi dan Tata Kerja Badan Perpustakaan Daerah&nbsp;Provinsi Sulawesi Tengah.</p>\r\n<p style=\"text-align: justify;\">Dalam rangka melaksanakan efektivitas penyelenggaraan pemerintahan dan pembangunan yang diselengarakan oleh Organisasi Perangkat Daerah perlu disesuaikan dengan kebutuhan dan kemampuan keuangan daerah. Oleh karena itu diperlukan adanya Pedoman Susunan Organisasi Tata Kerja Satuan Perangkat Daerah (SKPD) dengan diterbitkannya Peraturan Pemerintah No. 41 Tahun 2007 tentang Organisasi Perangkat Daerah. Konsekwensi dari implementasi PP No. 41 Tahun 2007 tersebut Badan Perpustakaan Daerah mengalami penggabungan dengan Kantor Arsip Daerah berdasarkan Peraturan Daerah Nomor 07 Tahun 2008 tentang Organisasi dan Tata Kerja Inspektorat, Badan Perencanaan Pembangunan dan Lembaga Teknis Daerah Provinsi Sulawesi Tengah sehingga nomenklatur organisasi berubah nama menjadi Badan Perpustakaan, Arsip dan Dokumentasi Daerah Provinsi Sulawesi Tengah. Selanjutnya dengan adanya perubahan Peraturan Pemerintah Nomor 41 Tahun 2007 tentang Organisasi Perangkat Daerah menjadi Peraturan Pemerintah Nomor 18 Tahun 2016 tentang Organisasi Perangkat Daerah Badan Perpustakaan, Arsip dan Dokumentasi Daerah Provinsi Sulawesi Tengah berubah lagi menjadi Dinas Daerah sehingga nomenklaturnya menjadi Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah melalui Peraturan Daerah Nomor 8 Tahun 2016 tentang Pembentukan dan Susunan Perangkat Daerah Provinsi Sulawesi Tengah dan Peraturan Gubernur Nomor 43 Tahun 2016 tentang Kedudukan dan Susunan Organisasi Dinas Daerah Provinsi Sulawesi Tengah serta Peraturan Gubernur Sulawesi Tengah Nomor 73 Tahun 2016 tentang Uraian Tugas, Fungsi dan Tata Kerja Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah.</p>', 'Admin Website', 'Admin Website', '2026-08-28 13:13:50', '2026-09-21 14:15:21');
