INSERT INTO `pamflet` (`id`, `nm_pamflet`, `slug_pamflet`, `gambar`, `deskripsi`, `status_id`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'IKM Tahun 2025 Semester I', 'ikm-tahun-2025-semester-i', '[\"20260908004452_CX5bynfzE0PlENR2.jpeg\"]', '<p class=\"PDq2pG_selectionAnchorContainer\" data-start=\"0\" data-end=\"61\"><strong data-start=\"0\" data-end=\"61\">📊 Indeks Kepuasan Masyarakat (IKM) Semester I Tahun 2025</strong></p>\r\n<p data-start=\"63\" data-end=\"241\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah terus berkomitmen menghadirkan pelayanan publik yang berkualitas, mudah diakses, dan sesuai dengan kebutuhan masyarakat.</p>\r\n<p data-start=\"243\" data-end=\"417\">Berdasarkan hasil <strong data-start=\"261\" data-end=\"326\">Survei Indeks Kepuasan Masyarakat (IKM) Semester I Tahun 2025</strong> pada bidang <strong data-start=\"339\" data-end=\"399\">Layanan, Alihmedia, Otomasi, dan Kerja Sama Perpustakaan</strong>, diperoleh nilai:</p>\r\n<p data-start=\"419\" data-end=\"496\">⭐ <strong data-start=\"421\" data-end=\"436\">IKM: 85,019</strong><br data-start=\"436\" data-end=\"439\">⭐ <strong data-start=\"441\" data-end=\"459\">Kategori: BAIK</strong><br data-start=\"459\" data-end=\"462\">👥 <strong data-start=\"465\" data-end=\"496\">Jumlah Responden: 150 Orang</strong></p>\r\n<p data-start=\"498\" data-end=\"766\">Terima kasih kepada seluruh masyarakat yang telah memberikan penilaian, masukan, dan saran. Setiap tanggapan yang diberikan menjadi bahan evaluasi bagi kami untuk terus melakukan perbaikan dan meningkatkan kualitas layanan perpustakaan bagi masyarakat Sulawesi Tengah.</p>\r\n<p data-start=\"768\" data-end=\"890\">Mari bersama membangun pelayanan perpustakaan yang semakin inovatif, responsif, dan berorientasi pada kepuasan masyarakat.</p>\r\n<p data-start=\"892\" data-end=\"1009\">📚 <strong data-start=\"895\" data-end=\"956\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah</strong><br data-start=\"956\" data-end=\"959\"><em data-start=\"959\" data-end=\"1009\">Melayani masyarakat, memperkuat budaya literasi.</em></p>\r\n<p data-start=\"1011\" data-end=\"1298\" data-is-last-node=\"\" data-is-only-node=\"\">#DispusakaSulteng #DinasPerpustakaanSulteng #IndeksKepuasanMasyarakat #IKM2025 #SurveiKepuasanMasyarakat #PelayananPublik #PerpustakaanSulteng #SulawesiTengah #Palu #LiterasiIndonesia #BudayaLiterasi #TransformasiPerpustakaan #PerpustakaanUntukMasyarakat #BerAKHLAK #BanggaMelayaniBangsa</p>', 1, 'Agustian Lagentu', 'Admin Website', NULL, '2026-09-07 16:44:52'),
(2, 'Jadwal Layanan Perpustakaan', 'jadwal-layanan-perpustakaan', '[\"20260908004352_KZ4hVsBQjwgwhJT5.jpg\"]', '<p class=\"PDq2pG_selectionAnchorContainer\" data-start=\"0\" data-end=\"64\"><strong data-start=\"0\" data-end=\"64\">📢 Pengumuman Jam Operasional Gedung Layanan Perpustakaan 📚</strong></p>\r\n<p data-start=\"66\" data-end=\"229\">Halo Sahabat Literasi!<br data-start=\"88\" data-end=\"91\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah menyampaikan informasi mengenai <strong data-start=\"181\" data-end=\"228\">jam operasional Gedung Layanan Perpustakaan</strong>.</p>\r\n<p data-start=\"231\" data-end=\"306\">Silakan kunjungi dan manfaatkan layanan perpustakaan sesuai jadwal berikut:</p>\r\n<p data-start=\"308\" data-end=\"353\">🗓 <strong data-start=\"311\" data-end=\"328\">Senin &ndash; Kamis</strong><br data-start=\"328\" data-end=\"331\">⏰ 08.00 &ndash; 16.00 WITA</p>\r\n<p data-start=\"355\" data-end=\"427\">🗓 <strong data-start=\"358\" data-end=\"367\">Jumat</strong><br data-start=\"367\" data-end=\"370\">⏰ 08.00 &ndash; 16.30 WITA<br data-start=\"390\" data-end=\"393\">🕌 Istirahat: 11.30 &ndash; 13.00 WITA</p>\r\n<p data-start=\"429\" data-end=\"466\">🗓 <strong data-start=\"432\" data-end=\"441\">Sabtu</strong><br data-start=\"441\" data-end=\"444\">⏰ 08.00 &ndash; 14.00 WITA</p>\r\n<p data-start=\"468\" data-end=\"518\">📌 <strong data-start=\"471\" data-end=\"518\">Hari Libur Nasional dan Cuti Bersama: Tutup</strong></p>\r\n<p data-start=\"520\" data-end=\"699\">Untuk informasi lebih lanjut, hubungi layanan kami:<br>📱 <strong data-start=\"575\" data-end=\"597\">0823 &ndash; 2022 &ndash; 2290</strong><br data-start=\"597\" data-end=\"600\"><em data-start=\"600\" data-end=\"699\">(Hanya dibuka pada jam kerja layanan perpustakaan. Tidak menerima telepon, hanya menerima pesan.)</em></p>\r\n<p data-start=\"701\" data-end=\"817\">Mari manfaatkan perpustakaan sebagai ruang belajar, mencari informasi, dan mengembangkan budaya literasi masyarakat.</p>\r\n<p data-start=\"819\" data-end=\"905\">📍 Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah<br data-start=\"879\" data-end=\"882\">Jl. Banteng No. 6, Palu</p>\r\n<p data-start=\"907\" data-end=\"1155\" data-is-last-node=\"\" data-is-only-node=\"\">#DispusakaSulteng #DinasPerpustakaanSulteng #JamOperasionalPerpustakaan #LayananPerpustakaan #PerpustakaanSulteng #SulawesiTengah #Palu #LiterasiIndonesia #BudayaMembaca #PerpustakaanUntukMasyarakat #PelayananPublik #BerAKHLAK #BanggaMelayaniBangsa</p>', 1, 'Agustian Lagentu', 'Admin Website', '2025-01-29 08:28:10', '2026-09-07 16:43:52'),
(3, 'Survey Kepuasan Masyarakat', 'survey-kepuasan-masyarakat', '[\"20260908004247_3ocUkpvrHrHel6h4.jpg\"]', '<p class=\"PDq2pG_selectionAnchorContainer\" data-start=\"0\" data-end=\"81\"><strong data-start=\"0\" data-end=\"81\">📢 Mari Berikan Penilaian untuk Meningkatkan Kualitas Layanan Perpustakaan 📚</strong></p>\r\n<p data-start=\"83\" data-end=\"270\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah mengajak seluruh pengguna layanan perpustakaan untuk berpartisipasi dalam <strong data-start=\"215\" data-end=\"269\">Survei Kepuasan Masyarakat (SKM) Semester I (Satu)</strong>.</p>\r\n<p data-start=\"272\" data-end=\"485\">Pendapat, kritik, dan saran dari masyarakat menjadi bahan evaluasi penting bagi kami dalam memperbaiki serta meningkatkan kualitas pelayanan agar semakin mudah, cepat, dan sesuai dengan kebutuhan pengguna layanan.</p>\r\n<p data-start=\"487\" data-end=\"600\">📝 Pengisian survei dapat dilakukan melalui:<br>🔗 <strong data-start=\"535\" data-end=\"565\"><a class=\"decorated-link cursor-pointer\" target=\"_new\" rel=\"noopener\" data-start=\"537\" data-end=\"563\">https://s.id/SKM_Dispusaka</a></strong><br data-start=\"565\" data-end=\"568\">📲 Atau scan barcode pada poster</p>\r\n<p data-start=\"602\" data-end=\"684\">Partisipasi Anda sangat berarti dalam mewujudkan pelayanan publik yang lebih baik.</p>\r\n<p data-start=\"686\" data-end=\"728\">Terima kasih atas waktu dan kontribusinya.</p>\r\n<p data-start=\"730\" data-end=\"846\">📚 <strong data-start=\"733\" data-end=\"794\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah</strong><br data-start=\"794\" data-end=\"797\"><em data-start=\"797\" data-end=\"846\">Melayani masyarakat, membangun budaya literasi.</em></p>\r\n<p data-start=\"848\" data-end=\"1102\" data-is-last-node=\"\" data-is-only-node=\"\">#DispusakaSulteng #DinasPerpustakaanSulteng #SurveiKepuasanMasyarakat #SKM #PelayananPublik #PerpustakaanSulteng #SulawesiTengah #Palu #LiterasiIndonesia #BudayaLiterasi #PerpustakaanUntukMasyarakat #TransformasiPelayanan #BerAKHLAK #BanggaMelayaniBangsa</p>', 1, 'Agustian Lagentu', 'Admin Website', '2025-01-29 08:30:26', '2026-09-07 16:42:47'),
(4, 'Permohonan Bebas Pustaka', 'permohonan-bebas-pustaka', '[\"20260908002607_Xvfe0b7aBUZriFWK.jpg\"]', '<p class=\"PDq2pG_selectionAnchorContainer\" data-start=\"0\" data-end=\"66\"><strong data-start=\"0\" data-end=\"66\">📚 Permohonan Surat Keterangan Bebas Pustaka Kini Lebih Mudah!</strong></p>\r\n<p data-start=\"68\" data-end=\"249\">Bagi mahasiswa yang membutuhkan <strong data-start=\"100\" data-end=\"134\">Surat Keterangan Bebas Pustaka</strong>, Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah menyediakan layanan dengan alur yang praktis dan mudah.</p>\r\n<p data-start=\"251\" data-end=\"473\">Pastikan persyaratan telah disiapkan:<br>✅ Foto copy kartu mahasiswa atau surat keterangan aktif kuliah<br data-start=\"351\" data-end=\"354\">✅ Mengisi formulir Bebas Pustaka melalui link yang tersedia<br data-start=\"413\" data-end=\"416\">✅ Pastikan tidak memiliki pinjaman koleksi perpustakaan</p>\r\n<p data-start=\"475\" data-end=\"621\">Ikuti alurnya:<br>1️⃣ Menyiapkan persyaratan<br data-start=\"516\" data-end=\"519\">2️⃣ Mengisi formulir permohonan<br data-start=\"550\" data-end=\"553\">3️⃣ Proses verifikasi permohonan<br data-start=\"585\" data-end=\"588\">4️⃣ Penerbitan surat keterangan</p>\r\n<p data-start=\"623\" data-end=\"778\">Mari manfaatkan layanan perpustakaan dengan tertib dan nyaman.<br data-start=\"685\" data-end=\"688\">Untuk informasi lebih lanjut, hubungi layanan perpustakaan melalui WhatsApp yang tersedia.</p>\r\n<p data-start=\"780\" data-end=\"865\">📍Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah<br data-start=\"839\" data-end=\"842\">Jl. Banteng No. 6, Palu</p>\r\n<p data-start=\"867\" data-end=\"1073\" data-is-last-node=\"\" data-is-only-node=\"\">#DispusakaSulteng #DinasPerpustakaan #PerpustakaanSulteng #SulawesiTengah #Palu #LayananPerpustakaan #BebasPustaka #InformasiPublik #PelayananPublik #LiterasiIndonesia #PerpustakaanDigital #MahasiswaSulteng</p>', 1, 'Agustian Lagentu', 'Admin Website', '2025-01-29 08:31:19', '2026-09-07 16:26:07'),
(5, 'IKM Tahun 2024 Semester I', 'ikm-tahun-2024-semester-i', '[\"20260908002718_ImLI7SDLlcot37Qn.jpg\"]', '<p class=\"PDq2pG_selectionAnchorContainer\" data-start=\"0\" data-end=\"61\"><strong data-start=\"0\" data-end=\"61\">📊 Indeks Kepuasan Masyarakat (IKM) Semester 1 Tahun 2026</strong></p>\r\n<p data-start=\"63\" data-end=\"274\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah mengucapkan <strong data-start=\"133\" data-end=\"149\">terima kasih</strong> kepada seluruh masyarakat yang telah berpartisipasi memberikan penilaian dan masukan terhadap kualitas layanan perpustakaan.</p>\r\n<p data-start=\"276\" data-end=\"426\">Berdasarkan hasil survei dengan jumlah <strong data-start=\"315\" data-end=\"332\">150 responden</strong>, diperoleh nilai <strong data-start=\"350\" data-end=\"400\">Indeks Kepuasan Masyarakat (IKM) sebesar 83,91</strong> dengan kategori <strong data-start=\"417\" data-end=\"425\">BAIK</strong>.</p>\r\n<p data-start=\"428\" data-end=\"638\">Masukan dan penilaian yang diberikan menjadi bahan evaluasi bagi kami untuk terus melakukan perbaikan serta meningkatkan kualitas pelayanan publik yang lebih mudah, cepat, dan responsif bagi seluruh masyarakat.</p>\r\n<p data-start=\"640\" data-end=\"724\">Mari bersama membangun budaya literasi dan pelayanan perpustakaan yang semakin baik.</p>\r\n<p data-start=\"726\" data-end=\"819\">📚 <strong data-start=\"729\" data-end=\"790\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah</strong><br data-start=\"790\" data-end=\"793\">📍 Jl. Banteng No. 6, Palu</p>\r\n<p data-start=\"821\" data-end=\"1048\" data-is-last-node=\"\" data-is-only-node=\"\">#DispusakaSulteng #DinasPerpustakaanSulteng #IndeksKepuasanMasyarakat #IKM #PelayananPublik #PerpustakaanSulteng #SulawesiTengah #Palu #LiterasiIndonesia #TransformasiPelayananPublik #BudayaLiterasi #PerpustakaanUntukMasyarakat</p>', 1, 'Agustian Lagentu', 'Admin Website', '2025-01-29 08:32:23', '2026-09-07 16:27:18'),
(6, 'IKM Tahun 2024 Semester II', 'ikm-tahun-2024-semester-ii', '[\"20260908003126_AcYCjpGhPF3OxLNZ.jpeg\"]', '<p class=\"PDq2pG_selectionAnchorContainer\" data-start=\"0\" data-end=\"62\"><strong data-start=\"0\" data-end=\"62\">📊 Indeks Kepuasan Masyarakat (IKM) Semester II Tahun 2024</strong></p>\r\n<p data-start=\"64\" data-end=\"228\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah terus berkomitmen memberikan pelayanan publik yang berkualitas dan berorientasi pada kebutuhan masyarakat.</p>\r\n<p data-start=\"230\" data-end=\"429\">Berdasarkan hasil survei <strong data-start=\"255\" data-end=\"330\">Indeks Kepuasan Masyarakat (IKM) Semester II Periode Juli&ndash;Desember 2024</strong>, dengan jumlah <strong data-start=\"346\" data-end=\"363\">150 responden</strong>, diperoleh nilai <strong data-start=\"381\" data-end=\"403\">IKM sebesar 84,148</strong> dengan kategori <strong data-start=\"420\" data-end=\"428\">BAIK</strong>.</p>\r\n<p data-start=\"431\" data-end=\"676\">Terima kasih kepada seluruh masyarakat yang telah memberikan penilaian, kritik, dan masukan. Setiap tanggapan yang diberikan menjadi bahan evaluasi bagi kami untuk terus memperbaiki serta meningkatkan kualitas layanan perpustakaan dan kearsipan.</p>\r\n<p data-start=\"678\" data-end=\"765\">Mari bersama mewujudkan pelayanan publik yang semakin mudah, transparan, dan responsif.</p>\r\n<p data-start=\"767\" data-end=\"884\">📚 <strong data-start=\"770\" data-end=\"831\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah</strong><br data-start=\"831\" data-end=\"834\">📍 Melayani masyarakat, mendukung budaya literasi.</p>\r\n<p data-start=\"886\" data-end=\"1118\" data-is-last-node=\"\" data-is-only-node=\"\">#DispusakaSulteng #DinasPerpustakaanSulteng #IndeksKepuasanMasyarakat #IKM #PelayananPublik #ZonaIntegritas #BerAKHLAK #PerpustakaanSulteng #SulawesiTengah #Palu #LiterasiIndonesia #TransformasiPelayanan #PerpustakaanUntukMasyarakat</p>', 1, 'Agustian Lagentu', 'Admin Website', '2025-01-29 08:32:37', '2026-09-07 16:31:26'),
(7, 'Pendaftaran Keanggotaan Perpustakaan', 'pendaftaran-keanggotaan-perpustakaan', '[\"20260908003235_7RgRTVoihgArrdpn.jpg\"]', '<p>\"Hallo Sobat Perpustakaan! 🙌🏻<br>Mari bergabung menjadi Anggota Perpustakaan Sulawesi Tengah! Bikin kartu anggota? Gratis! ✨\"<br><br>Sekarang pendaftaran anggota perpustakaan sudah tersedia secara online, tanpa perlu repot datang langsung. ✨<br>💻 Proses simpel<br>⏱️ Hemat waktu<br>📍 Bisa diakses dari mana saja<br><br>\"Satu kunjungan ke perpustakaan bisa mengubah cara pandangmu. Yuk, daftar jadi anggota perpustakaan melalui google forms yang disediakan! 📚\"<br><br>🔗 Link pendaftaran:<br>https://tinyurl.com/keanggotaanperpussulteng<br><br>📝 Pastikan mengisi data dengan benar, lengkap, dan sesuai identitas untuk memudahkan proses verifikasi pendaftaran.<br><br>Untuk informasi lebih lanjut, dapat menghubungi nomor whatsapp layanan perpustakaan : 0823-2022-2290<br><br><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz  _aa9_ _a6hd\" tabindex=\"0\" role=\"link\" href=\"https://www.instagram.com/explore/tags/perpustakaan/\">#Perpustakaan</a>&nbsp;<a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz  _aa9_ _a6hd\" tabindex=\"0\" role=\"link\" href=\"https://www.instagram.com/explore/tags/perpustakaanonline/\">#PerpustakaanOnline</a>&nbsp;<a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz  _aa9_ _a6hd\" tabindex=\"0\" role=\"link\" href=\"https://www.instagram.com/explore/tags/pendaftaranonline/\">#PendaftaranOnli