INSERT INTO `tugas` (`id`, `tugas_fungsi`, `link_google`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, '<p style=\"text-align: justify;\"><strong data-start=\"25\" data-end=\"103\">Tugas dan Fungsi Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah</strong> berdasarkan <strong data-start=\"116\" data-end=\"241\">Pergub Sulawesi Tengah Nomor 73 Tahun 2016 tentang Tugas, Fungsi dan Tata Kerja Dinas Perpustakaan dan Kearsipan Provinsi</strong>.</p>\r\n<p style=\"text-align: justify;\">Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah mempunyai tugas utama&nbsp;<strong data-start=\"394\" data-end=\"570\">membantu Gubernur melaksanakan urusan pemerintahan di bidang perpustakaan dan kearsipan yang menjadi kewenangan daerah serta tugas pembantuan yang diberikan kepada Provinsi</strong>. Dalam menjalankan tugas tersebut, Dinas melaksanakan fungsi perumusan kebijakan, pelaksanaan program, evaluasi, pelaporan, administrasi, serta tugas kedinasan lain yang diberikan oleh Gubernur.</p>\r\n<p style=\"text-align: justify;\">Secara lebih rinci, tugas dan fungsi tersebut dilaksanakan melalui beberapa unit kerja berikut :</p>\r\n<ol>\r\n<li style=\"text-align: justify;\"><strong>Sekretariat :</strong> Mengelola administrasi Dinas yang mencakup program, perencanaan, keuangan, aset, kepegawaian, urusan umum, rumah tangga dan Korpri. Sekretariat juga mengoordinasikan penyusunan rencana kerja, melakukan pengendalian, pemantauan, evaluasi dan pelaporan administrasi Dinas.</li>\r\n<li style=\"text-align: justify;\"><strong>Subbagian Program :</strong> Menyiapkan perencanaan dan program kerja Dinas melalui pengumpulan, pengolahan dan analisis data. Unit ini juga menyusun dokumen perencanaan dan pelaporan seperti Renja, LAKIP, LKPJ, LPPD, RPJMD dan Renstra serta melaksanakan monitoring dan evaluasi program.</li>\r\n<li style=\"text-align: justify;\"><strong>Subbagian Keuangan dan Aset :</strong> Mengelola administrasi keuangan dan aset, perbendaharaan, verifikasi keuangan, pembayaran gaji, penerimaan bukan pajak daerah, pemeliharaan barang milik daerah serta evaluasi dan pelaporan pengelolaan keuangan dan aset.</li>\r\n<li style=\"text-align: justify;\"><strong>Subbagian Kepegawaian dan Umum :</strong> Mengelola administrasi kepegawaian, rumah tangga, persuratan, kehumasan, dokumentasi dan pelayanan umum. Termasuk pengurusan kenaikan pangkat, gaji berkala, data kepegawaian, jabatan fungsional, rapat, penerimaan tamu, kebersihan dan keamanan kantor.</li>\r\n<li style=\"text-align: justify;\"><strong>Bidang Deposit, Pengembangan Koleksi, Pengolahan dan Konservasi Bahan Perpustakaan :</strong> Merumuskan dan melaksanakan kebijakan teknis terkait deposit, pengembangan koleksi, pengolahan serta konservasi bahan perpustakaan. Bidang ini juga melakukan pembinaan, koordinasi, monitoring, evaluasi dan pelaporan.</li>\r\n<li style=\"text-align: justify;\"><strong>Bidang Layanan, Alih Media, Otomasi dan Kerja Sama Perpustakaan :</strong> Menyelenggarakan layanan perpustakaan, kerja sama dan jejaring perpustakaan, pelestarian informasi melalui alih media serta pengembangan sistem otomasi, perangkat lunak, pangkalan data, jaringan dan website perpustakaan.</li>\r\n<li style=\"text-align: justify;\"><strong>Bidang Pengembangan Perpustakaan dan Pembudayaan Kegemaran Membaca :</strong> Membina dan mengembangkan kelembagaan perpustakaan serta tenaga perpustakaan. Bidang ini juga menjalankan program peningkatan minat baca, sosialisasi budaya membaca, pengkajian minat baca masyarakat dan evaluasi pengembangan perpustakaan.</li>\r\n<li style=\"text-align: justify;\"><strong>Bidang Pembinaan dan Pengawasan Kearsipan :</strong> Menyusun dan melaksanakan kebijakan pembinaan serta pengawasan kearsipan pada perangkat daerah, perusahaan, organisasi kemasyarakatan, organisasi politik dan masyarakat. Kegiatannya mencakup bimbingan teknis, konsultasi, sosialisasi, supervisi, audit kearsipan dan pembinaan SDM kearsipan.</li>\r\n<li style=\"text-align: justify;\"><strong>Bidang Pengelolaan dan Pengawasan Arsip :</strong> Mengelola arsip dinamis dan statis, melakukan akuisisi, pengolahan dan preservasi arsip, serta mengembangkan pemanfaatan arsip statis dan sistem informasi kearsipan. Bidang ini juga menjalankan layanan arsip, penelusuran arsip, pameran arsip serta pengelolaan informasi kearsipan.</li>\r\n<li style=\"text-align: justify;\"><strong>Kelompok Jabatan Fungsional :</strong> Melaksanakan tugas profesional sesuai jenis, keahlian, keterampilan dan jenjang jabatan fungsional berdasarkan ketentuan peraturan perundang-undangan.</li>\r\n</ol>', 'https://drive.google.com/file/d/1MiFi9DKhSi90YWMbQGDNstaonGHL4BXx/view?usp=drive_link', 'Admin Website', 'Admin Website', '2026-08-28 17:56:03', '2026-08-28 17:56:03');
INSERT INTO `tugasppids` (`id`, `tugasutama`, `tugaspelaksana`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, '<ol>\r\n<li><strong>Mengkoordinasikan penyimpanan, pendokumentasian, penyediaan, dan&nbsp;pelayanan informasi publik</strong> di badan publik.</li>\r\n<li><strong>Menetapkan dan mengumumkan Daftar Informasi Publik (DIP)</strong> secara berkala.</li>\r\n<li><strong>Menjamin ketersediaan informasi publik yang mudah diakses</strong>, baik secara manual maupun melalui media elektronik.</li>\r\n<li><strong>Melakukan uji konsekuensi</strong> untuk informasi yang dikecualikan sesuai aturan.</li>\r\n<li><strong>Memberikan tanggapan atas permohonan informasi publik</strong> yang diajukan masyarakat.</li>\r\n<li><strong>Menyediakan laporan layanan informasi publik</strong> secara berkala kepada atasan langsung dan/atau Komisi Informasi.</li>\r\n<li><strong>Meningkatkan kualitas layanan informasi publik</strong> melalui evaluasi dan pembaruan sistem.</li>\r\n</ol>', '<ol>\r\n<li><strong>Membantu PPID utama</strong> dalam mengelola informasi di unit kerja masing-masing.</li>\r\n<li><strong>Menghimpun, mengolah, dan menyimpan informasi publik</strong> dari unit kerjanya.</li>\r\n<li><strong>Menyediakan data/informasi yang diminta oleh PPID utama</strong> untuk memenuhi&nbsp;permohonan masyarakat.</li>\r\n<li><strong>Menjamin keakuratan, kelengkapan, dan ketepatan waktu</strong> penyediaan informasi&nbsp;dari unit kerjanya.</li>\r\n<li><strong>Mengklasifikasikan informasi publik</strong> sesuai kategori (informasi wajib diumumkan,&nbsp;informasi tersedia setiap saat, informasi berkala, dan informasi dikecualikan).</li>\r\n<li><strong>Melaporkan pelaksanaan tugas pengelolaan informasi</strong> kepada PPID utama&nbsp;secara berkala.</li>\r\n<li><strong>Melakukan koordinasi internal</strong> jika ada permintaan informasi yang menyangkut lintas bidang/unit kerja.</li>\r\n</ol>', 'Admin Website', 'Admin Website', '2026-08-28 02:02:54', '2026-08-28 02:02:54');
